actions.script:
const out = ec.service.sync().name('ironstone.projects.PlanningServices.move#TimelineItem').parameters({workEffortId: itemWorkEffortId || '',
    startDay: shiftDays ? null : (startDay ?? null), dueDay: shiftDays ? null : (dueDay ?? null), shiftDays: shiftDays ? Number(shiftDays) : null,
    moveSubtree: moveSubtree === 'Y', autoSchedule: autoSchedule === 'Y'}).call() || {}
if (!ec.message.hasError() && out.message) ec.message.addMessage(out.message, 'success')

const out = ec.service.sync().name('ironstone.projects.PlanningServices.save#TimelineDependency').parameters({workEffortId: dependentId || '',
    toWorkEffortId: predecessorId || '', lagDays: lagDays || null}).call() || {}
if (!ec.message.hasError() && out.message) ec.message.addMessage(out.message, 'success')

// the key is dependent and predecessor joined by a bar (indexOf: the screen lint reads a split's argument as a regex, F49)
const key = String(dependencyKey || ''), bar = key.indexOf('|')
const dependent = bar < 0 ? key : key.substring(0, bar), predecessor = bar < 0 ? '' : key.substring(bar + 1)
const out = ec.service.sync().name('ironstone.projects.PlanningServices.remove#TimelineDependency').parameters({workEffortId: dependent || '',
    toWorkEffortId: predecessor || ''}).call() || {}
if (!ec.message.hasError() && out.message) ec.message.addMessage(out.message, 'success')

timelineFound = false; rowList = []; planRows = []
const L = (text) => ec.l10n.localize(text)
const theMode = ['items', 'plan', 'portfolio'].includes(mode) ? mode : 'items'
let project = rootWorkEffortId || null
if (!project && theMode === 'items') project = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || [])[0]?.key || null
if (!project && theMode === 'items') return
const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#Timeline').parameters({mode: theMode, rootWorkEffortId: project}).call() || {}
ec.message.clearErrors()
const timeline = out.timeline
if (!timeline || timeline.notAvailable) return
timelineFound = true
title = theMode === 'portfolio' ? L('Projects') : (timeline.project ? timeline.project.workEffortName + ' (' + timeline.project.workEffortId + ')' : L('Roadmap'))
const fmt = (day) => day ? ec.l10n.format(ec.l10n.parseTimestamp(day + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d') : ''
const span = (first, last) => first && last && first !== last ? fmt(first) + ' – ' + fmt(last) : fmt(last || first)
const names = {}
for (const row of timeline.rowList || []) names[row.workEffortId] = row.workEffortId
const waits = {}
for (const link of timeline.dependencyList || []) (waits[link.workEffortId] || (waits[link.workEffortId] = [])).push(link.toWorkEffortId
        + (link.lagDays ? ' +' + link.lagDays + 'd' : '') + (link.violated ? ' (' + L('late') + ')' : ''))
rowList = Array.from(timeline.rowList || []).map((row) => ({workEffortId: row.workEffortId, url: row.url || '',
    name: '  '.repeat(Math.min(row.depth || 0, 6)) + (row.workEffortName || row.workEffortId),
    whenText: row.childCount && !row.startDay && !row.dueDay ? span(row.spanStartDay, row.spanDueDay) : (span(row.startDay, row.dueDay) || L('No dates')),
    progressText: (row.progress || 0) + '%', statusLabel: row.statusLabel || '', waitsText: (waits[row.workEffortId] || []).join(', ')}))
planRows = Array.from(theMode === 'items' ? (timeline.planItemList || []) : []).map((plan) => ({name: plan.workEffortName, kind: plan.kindLabel,
    whenText: span(plan.startDay, plan.dueDay), statusLabel: plan.statusLabel, progressText: (plan.percentDone || 0) + '%'}))
dependencyCount = (timeline.dependencyList || []).length
// what the team may change here (items mode): the rows and plan items it may move, the dependencies
const label = (id, name) => id + (name && name !== id ? ' ' + name : '')
moveOptions = []
if (theMode === 'items') {
    for (const plan of Array.from(timeline.planItemList || [])) if (plan.canMove) moveOptions.push({key: plan.workEffortId, text: label(plan.workEffortId, plan.workEffortName)
            + ' · ' + plan.kindLabel})
    for (const row of Array.from(timeline.rowList || [])) if (row.canMove) moveOptions.push({key: row.workEffortId, text: label(row.workEffortId, row.workEffortName)})
}
itemOptions = Array.from(timeline.rowList || []).map((row) => ({key: row.workEffortId, text: label(row.workEffortId, row.workEffortName)}))
dependentOptions = Array.from(timeline.rowList || []).filter((row) => row.canMove).map((row) => ({key: row.workEffortId, text: label(row.workEffortId, row.workEffortName)}))
dependencyOptions = Array.from(timeline.dependencyList || []).map((link) => ({key: link.workEffortId + '|' + link.toWorkEffortId,
    text: link.workEffortId + ' ' + L('waits for') + ' ' + link.toWorkEffortId + (link.lagDays ? ' +' + link.lagDays + 'd' : '')}))
canChange = theMode === 'items' && !!(timeline.project && timeline.project.canUpdate)
projectParam = {rootWorkEffortId: timeline.project ? timeline.project.workEffortId : (project || null), moveSubtree: 'N', autoSchedule: 'N'}
